llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Ribavirin, the closest structural analogue sharing the D-ribose and carboxamide-azole core, has an absolute oral bioavailability of 52% in patients, directly supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Clofarabine, a related purine nucleoside analogue, shows approximately 50% oral bioavailability in patients, indicating that polar nucleoside analogues in this class can exceed the 20% threshold despite low passive permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Levovirin, the L-enantiomer of ribavirin, has only about 10% oral bioavailability in humans; because the query is a D-riboside, this low value has low transferability and does not overturn the D-riboside evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest D-riboside analogue ribavirin has direct absolute oral bioavailability values around 45–65%, well above the 20% threshold; the only low-bioavailability close analogue is the L-enantiomer, which is not representative of the query. Therefore predict high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental F measurement for the query molecule itself.",
    "Differences in nucleoside transporter affinity and first-pass metabolism between ribavirin and AICAR are not directly quantified.",
    "No data on food, dose, or formulation effects for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

